  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "IP",
      "years": [2019, 2020],
      "pattern": "shock",
      "direction": "decrease",
      "magnitude": "A/E drops from ~1.2 in 2017 to 0.24 in 2019 and 0.36 in 2020, roughly 0.8-0.9 below the surrounding level, then returns to ~1.25 in 2021 and remains elevated",
      "confidence": 0.95,
      "evidence": [
        "artifacts/ae_ip_by_year.csv: 2017 AE 1.211, 2018 AE 0.814, 2019 AE 0.239, 2020 AE 0.357, 2021 AE 1.232, 2024 AE 1.255",
        "computed evidence pack: IP best excursion 2019-2020 with level -0.880, score 11.1; abrupt one-off level change rather than a gradual build-up; Poisson z-scores are invalid for IP because the excursion dominates the scatter",
        "artifacts/ae_ip_termination.csv: pooled termination A/E by diagnosis is 0.988-1.033, so no diagnosis-specific recovery-rate anomaly explains the claims dip"
      ],
      "recommended_action": "Investigate IP claims data quality and expected-rate calculation for 2018-2020, including source claims files, eligibility/coding, reporting lags, and exposure denominators. Reconcile the very low 2019-2020 actuals. If the dip is a data or modelling error, correct the experience study and review IP pricing/valuation, noting that excluding the dip leaves a persistent ~1.25 A/E level in 2021-2024."
    }
  ]
}

